<template><section class="view on"><div class="card glass reveal"><div class="ch"><h3>Messages & Meetings</h3></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:12px;margin-bottom:18px"><div><label class="lab">Student / Parent</label><select v-model="meeting.student_id" class="field"><option value="">Choose student</option><option v-for="s in students" :key="s.studentId" :value="s.studentId">{{s.name}}</option></select></div><div><label class="lab">Date & time</label><input v-model="meeting.meeting_date" type="datetime-local" class="field"></div><div><label class="lab">Meeting link</label><input v-model="meeting.meeting_link" class="field" placeholder="https://meet.google.com/..." ></div><div><label class="lab">Reason</label><input v-model="meeting.meeting_reason" class="field" placeholder="Progress review"></div></div><button class="btn grad" @click="requestMeeting">Schedule meeting</button><p v-if="message" class="eyebrow" style="margin-top:10px">{{message}}</p></div><div class="card glass reveal" style="margin-top:18px"><div class="chat"><div class="clist"><TutorEmptyState v-if="!conversationList.length" title="No messages"/><button v-for="c in conversationList" :key="c.id" class="ci" :class="{on:activeConversationId===c.id}" @click="$emit('select-conversation',c.id)"><div class="av" :style="{background:c.gradient}">{{c.initials}}</div><div><div class="t">{{c.participantName}}</div><div class="s">{{c.subtitle}}</div></div></button></div><div class="thr" v-if="activeConversation"><div class="msgs"><div v-for="m in activeConversation.messages" :key="m.messageId" class="bub" :class="m.w">{{m.message}}</div></div><div class="cin"><input v-model="draft" class="field" placeholder="Type a reply…" @keydown.enter="send"><button class="btn grad" @click="send">Send</button></div></div></div></div></section></template>
<script setup>
import {computed,reactive,ref} from 'vue';import TutorEmptyState from '../../components/tutor/TutorEmptyState.vue';import {tutorApi} from '../../services/tutorApi'
const props=defineProps({conversations:{type:Object,required:true},activeConversationId:{type:String,required:true},students:{type:Array,default:()=>[]}});const emit=defineEmits(['select-conversation','send-message','toast']);const draft=ref(''),message=ref('');const conversationList=computed(()=>Object.values(props.conversations||{}));const activeConversation=computed(()=>props.conversations?.[props.activeConversationId]||null);const meeting=reactive({student_id:'',meeting_date:'',meeting_link:'',meeting_reason:''});function send(){if(!draft.value.trim())return;emit('send-message',props.activeConversationId,draft.value);draft.value=''}async function requestMeeting(){try{if(!meeting.student_id||!meeting.meeting_date)throw new Error('Choose a student and date/time');await tutorApi.requestMeeting(meeting);message.value='Meeting scheduled';emit('toast','Meeting created and student notified')}catch(e){message.value=e.message}}
</script>
